#include <stdio.h>
#include <stdlib.h>
#include "dk1/rom_image.h"
#include "dk1/scene_memory.h"
#include "dk1/scene_view.h"
#include "dk1/ppu_compositor.h"
int main(int argc,char**argv){Dk1OwnedRom o={0};Dk1RomImage r={0};Dk1RomIdentity id;Dk1SceneMemory*s=NULL;Dk1Rgba8*px=NULL,*bg=NULL;Dk1RgbaSurface out,bg1;Dk1SceneView v;unsigned long level,cx,cy,w,h;bool streamed=false;int rc=1;if(argc!=8){fprintf(stderr,"usage: %s ROM LEVEL X Y WIDTH HEIGHT OUTPUT.ppm\n",argv[0]);return 2;}level=strtoul(argv[2],NULL,0);cx=strtoul(argv[3],NULL,0);cy=strtoul(argv[4],NULL,0);w=strtoul(argv[5],NULL,0);h=strtoul(argv[6],NULL,0);if(level>=DK1_SCENE_LEVEL_COUNT||!w||!h||w>1024||h>512)return 2;if(!dk1_rom_load_file(argv[1],&o,&r)||!dk1_rom_identity(&r,&id)||!dk1_rom_identity_is_supported_rev2(&id))goto done;s=malloc(sizeof(*s));px=calloc(w*h,sizeof(*px));bg=calloc(w*h,sizeof(*bg));if(!s||!px||!bg||!dk1_scene_memory_load(&r,(uint16_t)level,false,false,s))goto done;out=(Dk1RgbaSurface){px,w,h,w};bg1=(Dk1RgbaSurface){bg,w,h,w};v=(Dk1SceneView){(uint16_t)cx,(uint16_t)cy,(uint16_t)w,(uint16_t)h};if(!dk1_scene_view_clamp(s,&v)||!dk1_ppu_compose_mode1(s,v.camera_x/2u,v.camera_y/2u,0u,v.camera_y,out))goto done;streamed=dk1_scene_render_bg1(&r,s,v,bg1);if(streamed){size_t i;for(i=0;i<w*h;i++)out.pixels[i]=bg1.pixels[i];}if(!dk1_surface_write_ppm(argv[7],out))goto done;printf("level=%lu callback=$%04X ppu=%u terrain=%u package=%u camera=%u,%u bounds=%u..%u source=%s\n",level,s->recipe.init_callback_b9,s->recipe.ppu_preset,s->recipe.terrain_profile,s->recipe.primary_vram_package,v.camera_x,v.camera_y,s->camera.minimum_x,s->camera.maximum_x,streamed?"stream-map":"vram");rc=0;done:free(bg);free(px);free(s);dk1_rom_free(&o);return rc;}
